   248	template <typename T>
   249	struct Lookup
   250	{
   251	  inline const T* get_value (hb_codepoint_t glyph_id, unsigned int num_glyphs) const
   252	  {
   253	    switch (u.format) {
   254	    case 0: return u.format0.get_value (glyph_id, num_glyphs);
   255	    case 2: return u.format2.get_value (glyph_id);
   256	    case 4: return u.format4.get_value (glyph_id);
   257	    case 6: return u.format6.get_value (glyph_id);
   258	    case 8: return u.format8.get_value (glyph_id);
   259	    default:return nullptr;
   260	    }
   261	  }
   262	
   263	  inline const T& get_value_or_null (hb_codepoint_t glyph_id, unsigned int num_glyphs) const
   264	  {
   265	    const T *v = get_value (glyph_id, num_glyphs);
   266	    return v ? *v : Null(T);
   267	  }
   268	
   269	  inline bool sanitize (hb_sanitize_context_t *c) const
   270	  {
   271	    TRACE_SANITIZE (this);
   272	    if (!u.format.sanitize (c)) return_trace (false);
   273	    switch (u.format) {
   274	    case 0: return_trace (u.format0.sanitize (c));
   275	    case 2: return_trace (u.format2.sanitize (c));
   276	    case 4: return_trace (u.format4.sanitize (c));
   277	    case 6: return_trace (u.format6.sanitize (c));
   278	    case 8: return_trace (u.format8.sanitize (c));
   279	    default:return_trace (true);
   280	    }
   281	  }
   282	
   283	  protected:
   284	  union {
   285	  HBUINT16              format;         /* Format identifier */
   286	  LookupFormat0<T>      format0;
   287	  LookupFormat2<T>      format2;
   288	  LookupFormat4<T>      format4;
   289	  LookupFormat6<T>      format6;
   290	  LookupFormat8<T>      format8;
   291	  } u;
   292	  public:
   293	  DEFINE_SIZE_UNION (2, format);
   294	};
